+     -1,   6, -15,  20, -15,   6,  -1,   0,   0,   0,
+      0,  -1,   6, -15,  20, -15,   6,  -1,   0,   0,
+      0,   0,  -1,   6, -15,  20, -15,   6,  -1,   0,
