+      0,       0,       0,       0,       0,       0,       0,       1,     1.5,     1.8,       2, 2.14286,  // NOLINT
+      0,       0,       0,       0,       0,       0,       0,       1,     1.6,       2, 2.28571,     2.5,  // NOLINT
+      0,       0,       0,       0,       0,       0,       0,       1, 1.66667, 2.14286,     2.5, 2.77778;  // NOLINT
