-// (SUM(input))^0xFF
-uint8_t ProtocolData::CalculateCheckSum(const uint8_t *input,
-                                        const uint32_t length) {
-  uint8_t sum = 0;
-  for (size_t i = 0; i < length; ++i) {
-    sum += input[i];
-  }
-  return sum ^ 0xFF;
-}
