+      break;  // got a full packet
+    }
+    if (rc < 0) {
+      return false;  // end of file reached
+    }
+  }
+
+  set_base_time_from_nmea_time(nmea_time, basetime_);
+  input_->init(config_.firing_data_port);
+  return true;
+}
 
