+double TrajectoryCost::GetCostFromObsSL(
+    const double adc_s, const double adc_l,
+    const SLBoundary &obs_sl_boundary) const {
+  const auto &vehicle_param =
+      common::VehicleConfigHelper::instance()->GetConfig().vehicle_param();
+
