+  std::ifstream ifs(filename.c_str());
+  if (!ifs.is_open()) {
+    AERROR << "Failed to open file " << filename;
+    return false;
+  }
+  ifs >> *frame_id >> *time_stamp;
+  for (int i = 0; i < 3; i++) {
+    for (int j = 0; j < 4; j++) {
+      ifs >> (*pose)(i, j);
+    }
+  }
+  return true;
+}
