-        eglDestroyStreamKHR(m_display, m_stream);
-    if (m_surface != EGL_NO_SURFACE)
-        eglDestroySurface(m_display, m_surface);
-
-    eglDestroyContext(m_display, m_context);
-    eglTerminate(m_display);
-    eglReleaseThread();
