+template <typename T>
+std::unordered_set<T> Intersection(const std::unordered_set<T>& s1,
+                                   const std::unordered_set<T>& s2) {
+  if (s1.size() < s2.size()) {
+    std::unordered_set<T> result;
+    for (const auto& v : s1) {
+      if (s2.count(v) > 0) {
+        result.insert(v);
+      }
+    }
+    return result;
+  } else {
+    return intersection(s2, s1);
+  }
+}
