+    for (const auto& decision : history_decision.object_decision()) {
+      if (PathObstacle::IsLongitudinalDecision(decision) &&
+          !decision.has_ignore()) {
+        prev_decision_map[history_decision.id()] = decision;
+        break;
+      }
