+    ObjectDecisionType decision;
+    if (iter == prev_decision_map.end()) {
+      decision.mutable_ignore();
+    } else {
+      decision = iter->second;
+    }
+    if (!path_obstacle->HasLongitudinalDecision() && decision.has_ignore()) {
+      if (!MapWithoutDecision(path_obstacle).ok()) {
