+  } else if (type == BoundaryType::KEEP_CLEAR) {
+    return "KEEP_CLEAR";
+  } else if (type == BoundaryType::OVERTAKE) {
+    return "OVERTAKE";
+  } else if (type == BoundaryType::STOP) {
