+  } else if (type == BoundaryType::YIELD) {
+    return "YIELD";
+  } else if (type == BoundaryType::UNKNOWN) {
+    return "UNKNOWN";
+  }
+  AWARN << "Unkown boundary type " << static_cast<int>(type)
+        << ", treated as UNKNOWN";
+  return "UNKNOWN";
+}
